-- Ownership: access-control. Approved HCM-1 local business grants; no fabricated audit events.
PERFORM set_config('hcm.tenant_id','local-dunder-mifflin',true);
UPDATE hcm.access_role SET system_role=true, protected_admin=(id='tenant-administrator') WHERE tenant_id='local-dunder-mifflin' AND id IN ('employee','manager','hr-specialist','tenant-administrator');
